INSERT INTO policy_brief (id, kode, periode, judul, status, ringkasan, rekomendasi, halaman, disusun_oleh_id, diperbarui, dibuat_pada, konten, sumber_narasi) OVERRIDING SYSTEM VALUE VALUES
  ('16b1de54-bd34-3609-b70e-37c2056b89ed', 'PB-2026-09', 'September 2026', 'Optimalisasi cold storage untuk serapan surplus kentang dan tomat', 'DISETUJUI', 'Surplus panen kentang dan tomat menekan harga di tingkat petani; kapasitas cold storage perlu diarahkan untuk menyerap kelebihan pasokan.', '["Alihkan surplus ke cold storage dengan kapasitas tersisa terbesar", "Hubungkan agregator dengan pembeli antardaerah", "Tetapkan harga serap minimum sementara untuk kentang", "Pantau risiko food loss pada lot berumur simpan pendek"]'::jsonb, 7, '4a5595b3-31f9-3231-97cc-91bb5aa27394', '2026-10-30T13:59:38.72247+00:00', '2026-10-27T13:59:38.72247+00:00', '{"label": "Draf otomatis (data demo)", "penyusun": "DEMO", "bagian": [{"judul": "Ringkasan Eksekutif", "isi": "Surplus panen kentang dan tomat menekan harga di tingkat petani; kapasitas cold storage perlu diarahkan untuk menyerap kelebihan pasokan."}, {"judul": "Rekomendasi Kebijakan", "isi": "Alihkan surplus ke cold storage dengan kapasitas tersisa terbesar\nHubungkan agregator dengan pembeli antardaerah\nTetapkan harga serap minimum sementara untuk kentang\nPantau risiko food loss pada lot berumur simpan pendek"}], "metrik_kunci": [], "lampiran": []}'::jsonb, 'DEMO'),
  ('2a9920a5-e625-3fe1-be1f-10e136e3abe1', 'PB-2026-07', 'Juli 2026', 'Pola distribusi ikan tongkol di wilayah pesisir timur', 'DIDISTRIBUSIKAN', 'Harga ikan tongkol di pesisir timur dipengaruhi cuaca laut dan rantai distribusi yang panjang menuju wilayah tengah.', '["Perpendek rantai distribusi dari pelabuhan ke pasar tengah", "Sediakan rantai dingin di titik pendaratan utama", "Sinkronkan jadwal pasokan dengan prakiraan cuaca laut", "Libatkan koperasi nelayan dalam pelaporan harga"]'::jsonb, 9, '4a5595b3-31f9-3231-97cc-91bb5aa27394', '2026-09-01T09:59:38.72247+00:00', '2026-08-29T09:59:38.72247+00:00', '{"label": "Draf otomatis (data demo)", "penyusun": "DEMO", "bagian": [{"judul": "Ringkasan Eksekutif", "isi": "Harga ikan tongkol di pesisir timur dipengaruhi cuaca laut dan rantai distribusi yang panjang menuju wilayah tengah."}, {"judul": "Rekomendasi Kebijakan", "isi": "Perpendek rantai distribusi dari pelabuhan ke pasar tengah\nSediakan rantai dingin di titik pendaratan utama\nSinkronkan jadwal pasokan dengan prakiraan cuaca laut\nLibatkan koperasi nelayan dalam pelaporan harga"}], "metrik_kunci": [], "lampiran": []}'::jsonb, 'DEMO'),
  ('3b124e4a-5309-3f91-b9c2-c6910fe080e5', 'PB-2026-06', 'Juni 2026', 'Kesiapan pasokan pangan Iduladha di 23 kabupaten/kota', 'DIDISTRIBUSIKAN', 'Permintaan daging, cabai, dan bawang meningkat menjelang Iduladha; kesiapan pasokan tiap kabupaten/kota perlu dipantau.', '["Petakan kabupaten/kota dengan neraca pangan defisit", "Jadwalkan operasi pasar sebelum puncak permintaan", "Amankan pasokan daging sapi dan ayam antardaerah", "Aktifkan peringatan dini untuk komoditas pilot", "Siapkan kanal pengaduan harga bagi masyarakat", "Evaluasi dampak kebijakan segera setelah hari raya"]'::jsonb, 10, '4a5595b3-31f9-3231-97cc-91bb5aa27394', '2026-08-02T13:19:38.72247+00:00', '2026-07-30T13:19:38.72247+00:00', '{"label": "Draf otomatis (data demo)", "penyusun": "DEMO", "bagian": [{"judul": "Ringkasan Eksekutif", "isi": "Permintaan daging, cabai, dan bawang meningkat menjelang Iduladha; kesiapan pasokan tiap kabupaten/kota perlu dipantau."}, {"judul": "Rekomendasi Kebijakan", "isi": "Petakan kabupaten/kota dengan neraca pangan defisit\nJadwalkan operasi pasar sebelum puncak permintaan\nAmankan pasokan daging sapi dan ayam antardaerah\nAktifkan peringatan dini untuk komoditas pilot\nSiapkan kanal pengaduan harga bagi masyarakat\nEvaluasi dampak kebijakan segera setelah hari raya"}], "metrik_kunci": [], "lampiran": []}'::jsonb, 'DEMO'),
  ('41ed31b7-b973-30d9-ac38-f89a7253f41a', 'PB-2026-08', 'Agustus 2026', 'Stabilisasi harga beras menjelang panen gadu', 'DIDISTRIBUSIKAN', 'Stok beras memadai untuk beberapa bulan konsumsi; harga diperkirakan stabil hingga panen gadu mulai masuk pasar.', '["Jaga ketersediaan stok Bulog di pasar rawan gejolak", "Percepat penyerapan gabah petani saat panen raya", "Lanjutkan pemantauan harga mingguan"]'::jsonb, 6, '4a5595b3-31f9-3231-97cc-91bb5aa27394', '2026-10-01T06:39:38.72247+00:00', '2026-09-28T06:39:38.72247+00:00', '{"label": "Draf otomatis (data demo)", "penyusun": "DEMO", "bagian": [{"judul": "Ringkasan Eksekutif", "isi": "Stok beras memadai untuk beberapa bulan konsumsi; harga diperkirakan stabil hingga panen gadu mulai masuk pasar."}, {"judul": "Rekomendasi Kebijakan", "isi": "Jaga ketersediaan stok Bulog di pasar rawan gejolak\nPercepat penyerapan gabah petani saat panen raya\nLanjutkan pemantauan harga mingguan"}], "metrik_kunci": [], "lampiran": []}'::jsonb, 'DEMO'),
  ('dfb2ba45-a711-317e-a45e-313f19d1ab43', 'PB-2026-10', 'Oktober 2026', 'Meredam tekanan harga cabai pascacurah hujan ekstrem di dataran tinggi Gayo', 'DRAF', 'Inflasi tahunan Aceh masih dalam koridor sasaran, namun curah hujan ekstrem di sentra Gayo menekan pasokan cabai merah dan mendorong harga naik.', '["Siapkan operasi pasar cabai di Pasar Peunayong dan Lamdingin", "Petakan pasokan alternatif dari Bireuen dan Sumatera Utara", "Ajukan dukungan subsidi ongkos angkut ke Kanwil DJPb", "Perkuat pemantauan harga harian di 11 pasar sentinel", "Koordinasikan jadwal tanam ulang dengan dinas pertanian dataran tinggi"]'::jsonb, 8, '4a5595b3-31f9-3231-97cc-91bb5aa27394', '2026-11-06T08:34:38.72247+00:00', '2026-11-03T08:34:38.72247+00:00', '{"label": "Draf otomatis (data demo)", "penyusun": "DEMO", "bagian": [{"judul": "Ringkasan Eksekutif", "isi": "Inflasi tahunan Aceh masih dalam koridor sasaran, namun curah hujan ekstrem di sentra Gayo menekan pasokan cabai merah dan mendorong harga naik."}, {"judul": "Rekomendasi Kebijakan", "isi": "Siapkan operasi pasar cabai di Pasar Peunayong dan Lamdingin\nPetakan pasokan alternatif dari Bireuen dan Sumatera Utara\nAjukan dukungan subsidi ongkos angkut ke Kanwil DJPb\nPerkuat pemantauan harga harian di 11 pasar sentinel\nKoordinasikan jadwal tanam ulang dengan dinas pertanian dataran tinggi"}], "metrik_kunci": [], "lampiran": []}'::jsonb, 'DEMO')
